//! Fixed exactly two adjacent sibling edges, not general complex has.
use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
use kobo_web_document::style_tree::StyleTree;
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(css:&str,b:&str,l:&Limits,s:&SnapshotState)->StyleTree{let h=format!("<!doctype html><style>{css}</style>{b}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],l,None,SupplyBudget::CANONICAL,s)}
#[test] fn browser_color9_both_compounds_rank(){let h=include_str!("fixtures/two_adjacent_has_cascade.html");let t=kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],&Limits::DEFAULT,None,SupplyBudget::CANONICAL,&snap());assert!(!t.unsupported && !t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="div").map(|n|n.style.color).collect::<Vec<_>>(),[0x0000ff,0xff0000,0xff0000,0x0000ff,0x0000ff,0x0000ff,0xff0000,0x0000ff,0xff0000]);}
#[test] fn tail_dependencies_wrong_families_autofocus_same_target_and_partial_loss(){let css=".absent:has(+.absent+:where(:not(:focus))){color:red}";let b="<div><section><p></p></section></div>";assert!(run(css,b,&Limits::DEFAULT,&snap()).unsupported);let mut s=snap();s.input=Some(InputState::QuiescentCapture);assert!(run(css,b,&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(css,b,&Limits::DEFAULT,&s).unsupported);assert!(run(css,"<div><section><p autofocus></p></section></div>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("tail".into()));let t=run("div:has(+section+:target){color:red}","<div></div><section></section><p id=tail></p>",&Limits::DEFAULT,&s);assert!(!t.unsupported);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0xff0000);for css in ["div:has(+section+:empty){color:red}","div:not(:has(+section+:empty)){color:red}","div:where(:has(+section+:empty)){color:red}"]{for l in [Limits{max_input_bytes:70,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(css,"<div></div><section></section><p>x</p>",&l,&snap());assert!(t.unsupported || t.truncated);}}}
#[test] fn public_real_tail_error_and_aggregate_global_work(){let b=format!("<div></div><section></section><p data-x='{}'></p><p data-x=aaaaab></p>","a".repeat(1000));let t=run("div:has(+section+[data-x*=aaaaab]){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.truncated);let one=format!("<section>{}</section>","<p></p>".repeat(100));let css="p:has(+p+.missing){color:red}";assert!(!run(css,&one,&Limits::DEFAULT,&snap()).truncated);let t=run(&css.repeat(10),&one.repeat(100),&Limits{max_nodes:20000,..Limits::DEFAULT},&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);assert_eq!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::DomNodes),0);}

#[test] #[ignore="measurement: TWO_ADJACENT_LINES original4 including2acceptedoneedgecontrols"]
fn original4_public_inventory(){let text=std::fs::read_to_string(std::env::var("TWO_ADJACENT_LINES").unwrap()).unwrap();let s=SnapshotState{history:Some(HistoryState::FreshNoHistory),input:Some(InputState::QuiescentCapture),focus:Some(FocusState::UnfocusedInitial),target:Some(TargetState::FragmentFreeCapture)};let mut total=0;let mut refused=Vec::new();for(i,l)in text.lines().enumerate(){total+=1;let t=run(&format!("{l}{{color:red}}"),"<div><section><p></p></section></div>",&Limits::DEFAULT,&s);let yes=!t.unsupported && !t.truncated;println!("TWO-ADJACENT-PUBLIC line={} admitted={} truncated={} first={:?}",i+1,yes,t.truncated,t.diagnostics.first_reason());if !yes{refused.push(i+1);}}assert_eq!(total,4);assert!(refused.is_empty());println!("TWO-ADJACENT-PUBLIC total={total} admitted={} refused={refused:?}",total-refused.len());}

#[test] fn real_first_predicate_error_before_tail_or_later_true(){let b=format!("<div></div><section data-x='{}'></section><p></p><section data-x=aaaaab></section><p></p>","a".repeat(1000));let t=run("div:has(+[data-x*=aaaaab]+p){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);}
